/*
 * Atelier — Krackle setup check (identity v1.0)
 * Classic-script IIFE adding window.AtelierMotion.setupCheck.
 *
 * The launch check draws the line the Projects page stands on. The host sits on a page
 * header's 1px rule (`.at-proj-hero`); the art is measured to the header's width:
 *   busy     a drop of ink on the left pours along the rule into a latch on the right,
 *            on the beat (two beats a pour, one a charge). The only loop.
 *   success  the latch becomes a starburst that pops, throwing four flecks (420ms once).
 *   warning  a cracked ring whose broken chunk falls and bounces (620ms once).
 *   error    the latch squeezes to a point and bursts into a splat with satellites and a
 *            drip; a dazed bubble circles to rest (~1.4s once).
 * On a result the drop and its pour go and the channel settles into the 1px rule.
 *
 * mount(host, {state, play}) returns setState, destroy. `play` performs a result that
 * arrives with the mount (the page appeared with its answer). The application owns the
 * request and its outcome; this file makes no API or storage calls. Full motion only:
 * Calm, Off, reduced motion and missing Web Animations show each state's final pose, and a
 * hidden document stops the loop. Artwork is generated by scripts/krackle_art.py.
 */
(function () {
  'use strict';

  var P = 'am-setup-check';
  var STATES = {busy: 1, success: 1, warning: 1, error: 1};
  var Y = 36.5;   // the rule's centre in the 72px band (see setup-check.css)
  var mounted = typeof WeakMap === 'function' ? new WeakMap() : null;

  // krackle-art:setup-check:begin
  var SVG_MARKUP = '<svg xmlns="http://www.w3.org/2000/svg" class="am-setup-check-svg" viewBox="0 0 520 72" width="520" height="72" aria-hidden="true" focusable="false" fill="currentColor"><path class="am-setup-check-track" d="M44 36 H320" /><path class="am-setup-check-pour" d="M44 36 H320" pathLength="1" /><g class="am-setup-check-drop" transform="translate(22 36)"><g class="am-setup-check-drop-ink"><circle class="am-setup-check-energy" cx="0" cy="0" r="18" /><circle class="am-setup-check-hole" cx="4" cy="5" r="4.2" /><circle class="am-setup-check-hole" cx="-2.5" cy="10.5" r="1.9" /><circle class="am-setup-check-hole" cx="9" cy="-3" r="1.6" /><circle class="am-setup-check-glint" cx="-6.5" cy="-7" r="1.6" /></g></g><g class="am-setup-check-latch" transform="translate(356 36)"><g class="am-setup-check-latch-ink"><path class="am-setup-check-energy" d="M-26 -22 H-10 Q0 -22 0 -12 V12 Q0 22 -10 22 H-26 Q-36 22 -36 12 V10 H-12 V-10 H-36 V-12 Q-36 -22 -26 -22 Z" /><circle class="am-setup-check-hole" cx="-6" cy="15" r="2.2" /></g></g><g class="am-setup-check-result am-setup-check-success" transform="translate(400 36)"><g class="am-setup-check-burst-ink"><path class="am-setup-check-energy am-setup-check-burst" d="M0 -24 L4.82 -11.64 L16.97 -16.97 L11.64 -4.82 L24 0 L11.64 4.82 L16.97 16.97 L4.82 11.64 L0 24 L-4.82 11.64 L-16.97 16.97 L-11.64 4.82 L-24 0 L-11.64 -4.82 L-16.97 -16.97 L-4.82 -11.64 Z" /><circle class="am-setup-check-hole" cx="4" cy="5" r="2.8" /><circle class="am-setup-check-glint" cx="-6" cy="-7" r="1.6" /></g><g class="am-setup-check-flecks"><circle class="am-setup-check-energy am-setup-check-fleck" cx="-30" cy="-22" r="2.6" /><circle class="am-setup-check-energy am-setup-check-fleck" cx="-31" cy="20" r="2.2" /><circle class="am-setup-check-energy am-setup-check-fleck" cx="22" cy="-27" r="2" /><circle class="am-setup-check-energy am-setup-check-fleck" cx="24" cy="26" r="2.4" /></g></g><g class="am-setup-check-result am-setup-check-warning" transform="translate(452 36)"><g class="am-setup-check-ring"><path class="am-setup-check-arc" d="M0.23 15 A15 15 0 1 1 13.47 6.6" /><circle class="am-setup-check-hole" cx="-14.1" cy="-5.1" r="1.6" /><circle class="am-setup-check-glint" cx="-5.1" cy="-14.1" r="1.3" /></g><g class="am-setup-check-chunk"><path class="am-setup-check-energy" d="M14 26 L23 24.5 L24.5 31 L15 32.5 Z" /><circle class="am-setup-check-hole" cx="19.2" cy="28.6" r="1.3" /></g></g><g class="am-setup-check-result am-setup-check-error" transform="translate(500 36)"><g class="am-setup-check-splat"><circle class="am-setup-check-energy" cx="0" cy="0" r="14.72" /><circle class="am-setup-check-energy" cx="-10.88" cy="5.12" r="8.32" /><circle class="am-setup-check-energy" cx="10.24" cy="-6.4" r="8.32" /><circle class="am-setup-check-energy" cx="7.68" cy="9.6" r="7.04" /><circle class="am-setup-check-energy" cx="-6.4" cy="-9.6" r="6.4" /><circle class="am-setup-check-hole" cx="1.28" cy="-0.64" r="5.5" /><circle class="am-setup-check-hole" cx="-9.6" cy="4.5" r="2.9" /><circle class="am-setup-check-glint" cx="-5.3" cy="-6.7" r="2" /></g><g class="am-setup-check-sats"><circle class="am-setup-check-energy am-setup-check-sat" cx="-28" cy="-12" r="2.9" /><circle class="am-setup-check-energy am-setup-check-sat" cx="29" cy="7" r="2.6" /><circle class="am-setup-check-energy am-setup-check-sat" cx="-21" cy="24" r="2.4" /><circle class="am-setup-check-energy am-setup-check-sat" cx="23" cy="-25" r="2.4" /><circle class="am-setup-check-energy am-setup-check-sat" cx="25" cy="25" r="1.9" /></g><g class="am-setup-check-drip"><path class="am-setup-check-drip-line" d="M-9 11.5 V21.5" /><circle class="am-setup-check-energy" cx="-9" cy="23.5" r="3.4" /></g><g class="am-setup-check-dizzy"><circle class="am-setup-check-energy" cx="-10" cy="-22" r="2.9" /><circle class="am-setup-check-hole" cx="-9.4" cy="-21.8" r="1.2" /></g></g></svg>';
  // krackle-art:setup-check:end

  function full() {
    if (document.documentElement.dataset.motion === 'reduce') return false;
    if (window.AtelierMotionPolicy) return window.AtelierMotionPolicy.allows(3);
    try { return !window.matchMedia('(prefers-reduced-motion: reduce)').matches; } catch (_) { return true; }
  }
  function beat() {
    var value = parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--beat'));
    return value > 0 ? value : (window.AtelierMotion && window.AtelierMotion.beatMs) || 1040;
  }

  function mount(host, options) {
    if (!host || host.nodeType !== 1) throw new Error('AtelierMotion.setupCheck.mount requires a DOM host.');
    var prior = mounted && mounted.get(host);
    if (prior) prior.destroy();
    if (host.childNodes.length) throw new Error('Setup check needs an empty host.');
    if (!SVG_MARKUP) throw new Error('Setup check artwork is missing.');

    var opts = options || {};
    var state = STATES[opts.state] ? opts.state : 'busy';
    var destroyed = false, running = [], resize = null;
    host.setAttribute('data-atelier-motion', 'setup-check');
    host.setAttribute('aria-hidden', 'true');
    host.innerHTML = SVG_MARKUP;
    var svg = host.firstElementChild;
    svg.removeAttribute('width');
    svg.removeAttribute('height');
    function q(sel) { return svg.querySelector('.' + P + '-' + sel); }
    function qa(sel) { return Array.prototype.slice.call(svg.querySelectorAll('.' + P + '-' + sel)); }
    var parts = {
      track: q('track'), pour: q('pour'), drop: q('drop'), latch: q('latch'),
      success: q('success'), warning: q('warning'), error: q('error'),
      burst: q('burst-ink'), flecks: qa('fleck'), ring: q('ring'), chunk: q('chunk'),
      splat: q('splat'), sats: qa('sat'), drip: q('drip'), dizzy: q('dizzy'),
      dropInk: q('drop-ink'), latchInk: q('latch-ink')
    };

    function measure() {
      if (destroyed) return;
      var w = Math.max(160, Math.round(host.clientWidth || 0));
      svg.setAttribute('viewBox', '0 0 ' + w + ' 72');
      var place = function (el, x) { if (el) el.setAttribute('transform', 'translate(' + x + ' ' + Y + ')'); };
      place(parts.drop, 22);
      place(parts.latch, w - 4);
      place(parts.success, w - 28);
      place(parts.warning, w - 28);
      place(parts.error, w - 32); // the splat's satellites reach further than the other results
      // Busy runs drop to latch; a result is the header rule itself, stopping short of its glyph.
      parts.track.setAttribute('d', state === 'busy' ? 'M44 ' + Y + ' H' + (w - 40) : 'M0 ' + Y + ' H' + (w - 60));
      parts.pour.setAttribute('d', 'M44 ' + Y + ' H' + (w - 36));
    }

    function cancel() {
      running.forEach(function (a) { try { a.cancel(); } catch (_) {} });
      running = [];
    }
    function sync() {
      if (destroyed) return;
      host.setAttribute('data-am-state', state);
      host.setAttribute('data-am-running', String(state === 'busy' && full() && !document.hidden));
    }
    function animate(el, frames, timing) {
      if (!el || typeof el.animate !== 'function') return;
      try { running.push(el.animate(frames, Object.assign({fill: 'backwards'}, timing))); } catch (_) {}
    }
    // A result performs once, then holds its final pose (the CSS pose); nothing is held back.
    function perform(from) {
      cancel();
      if (!full() || document.hidden || typeof svg.animate !== 'function') return;
      var pop = 'cubic-bezier(.34, 1.56, .64, 1)', settle = 'cubic-bezier(.2, .8, .2, 1)';
      if (from === 'busy') {
        animate(parts.track, [{strokeWidth: 3}, {strokeWidth: 1}], {duration: 400, easing: settle});
        animate(parts.dropInk, [{transform: 'scale(1)', opacity: 1}, {transform: 'scale(.2)', opacity: 0}], {duration: 200, easing: settle, fill: 'forwards'});
      }
      if (state === 'success') {
        animate(parts.burst, [{transform: 'scale(.3) rotate(-20deg)'}, {transform: 'scale(1.14) rotate(4deg)', offset: .6}, {transform: 'none'}], {duration: 420, easing: pop});
        parts.flecks.forEach(function (f, i) {
          animate(f, [{transform: 'scale(0)', opacity: 0}, {transform: 'scale(1)', opacity: 1}], {duration: 300, delay: 120 + i * 30, easing: settle});
        });
      } else if (state === 'warning') {
        animate(parts.ring, [{transform: 'scale(.6)'}, {transform: 'scale(1.08)', offset: .5}, {transform: 'none'}], {duration: 320, easing: settle});
        animate(parts.chunk, [
          {transform: 'translate(-11px, -18px) rotate(-30deg)'},
          {transform: 'translate(-11px, -18px) rotate(-30deg)', offset: .25},
          {transform: 'none', offset: .62, easing: 'cubic-bezier(.3, 0, .7, .4)'},
          {transform: 'translate(0, -4px) rotate(6deg)', offset: .8},
          {transform: 'none'}
        ], {duration: 620, easing: 'cubic-bezier(.55, 0, 1, .45)'});
      } else if (state === 'error') {
        animate(parts.splat, [
          {transform: 'scale(.8, .8)'}, {transform: 'scale(.18, .3)', offset: .22, easing: 'cubic-bezier(.55, 0, .8, .35)'},
          {transform: 'scale(1.18)', offset: .38}, {transform: 'none', offset: .5}, {transform: 'none'}
        ], {duration: 1400, easing: settle});
        parts.sats.forEach(function (s, i) {
          animate(s, [{transform: 'scale(0)', opacity: 0}, {transform: 'scale(0)', opacity: 0, offset: .3}, {transform: 'scale(1.2)', opacity: 1, offset: .45}, {transform: 'none', opacity: 1}],
            {duration: 1400, delay: i * 18, easing: settle});
        });
        animate(parts.drip, [{transform: 'scaleY(0)'}, {transform: 'scaleY(0)', offset: .45}, {transform: 'scaleY(1.1)', offset: .78}, {transform: 'none'}], {duration: 1400, easing: settle});
        animate(parts.dizzy, [
          {transform: 'translate(0, 6px)', opacity: 0}, {transform: 'translate(0, 6px)', opacity: 0, offset: .5},
          {transform: 'translate(14px, 2px)', opacity: 1, offset: .62}, {transform: 'translate(17px, -1px)', offset: .72},
          {transform: 'translate(6px, -2px)', offset: .84}, {transform: 'none'}
        ], {duration: 1400, easing: 'linear'});
      }
    }

    function onEnvironment() {
      if (destroyed) return;
      if (!full() || document.hidden) cancel();
      sync();
    }
    document.addEventListener('visibilitychange', onEnvironment);
    window.addEventListener('atelier:preferences', onEnvironment);
    if (typeof ResizeObserver === 'function') { resize = new ResizeObserver(measure); resize.observe(host); }
    else window.addEventListener('resize', measure);
    host.style.setProperty('--am-setup-check-beat', beat() + 'ms');
    measure();
    sync();
    if (opts.play && state !== 'busy') perform(null);

    var handle = {
      setState: function (next) {
        if (destroyed || !STATES[next] || next === state) return;
        var from = state;
        state = next;
        measure();
        sync();
        perform(from);
      },
      destroy: function () {
        if (destroyed) return;
        destroyed = true;
        cancel();
        document.removeEventListener('visibilitychange', onEnvironment);
        window.removeEventListener('atelier:preferences', onEnvironment);
        if (resize) resize.disconnect(); else window.removeEventListener('resize', measure);
        if (svg.parentNode === host) host.removeChild(svg);
        ['data-atelier-motion', 'data-am-state', 'data-am-running', 'aria-hidden'].forEach(function (name) { host.removeAttribute(name); });
        host.style.removeProperty('--am-setup-check-beat');
        if (mounted && mounted.get(host) === handle) mounted.delete(host);
      }
    };
    if (mounted) mounted.set(host, handle);
    return handle;
  }

  window.AtelierMotion = window.AtelierMotion || {};
  window.AtelierMotion.setupCheck = Object.freeze({mount: mount});
})();
